//! CImageWidget e IInterfaceModel usam contratos numéricos do SDK Brew MP.
use std::path::PathBuf;
use zeebx::{brew::aee::{self,Interface},cpu::{BackendPadrao,CpuBackend},loader::{self,modfile::ModImage},machine::{Machine,Outcome},storage::StoragePaths};
struct F{m:Machine<BackendPadrao>,root:PathBuf,out:u32}
impl F{
 fn new()->Self{static NEXT:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);let root=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("local-tests/startup-repairs-wave21-20261031/wmapp").join(format!("widget-test-{}-{}",std::process::id(),NEXT.fetch_add(1,std::sync::atomic::Ordering::Relaxed)));std::fs::create_dir_all(&root).unwrap();let store=StoragePaths::from_root(root.join("runtime"));store.create_dirs().unwrap();let image=ModImage::parse([0xe3a00000u32,0xe12fff1e].into_iter().flat_map(u32::to_le_bytes).collect()).unwrap();let mut m=Machine::new_with_storage(BackendPadrao::new().unwrap(),loader::load_with(&image,&[]).unwrap(),&root,&store,None);assert_eq!(m.run(1000).unwrap(),Outcome::Returned{code:0});Self{m,root,out:loader::HEAP_BASE+0x4000}}
 fn entry(&mut self,entry:u32,args:[u32;4])->u32{match self.m.call_guest(entry,args,100000).unwrap(){Outcome::Returned{code}=>code,x=>panic!("{entry:#x}: {x:?}")}}
 fn call(&mut self,obj:u32,slot:u32,args:[u32;3])->u32{let vt=self.m.cpu().read_u32(obj).unwrap();let entry=self.m.cpu().read_u32(vt+slot*4).unwrap();self.entry(entry,[obj,args[0],args[1],args[2]])}
 fn api(&mut self,i:Interface,name:&str,args:[u32;4])->u32{let slot=(0..256).find(|s|i.method(*s)==Some(name)).unwrap();self.entry(aee::encode(i,slot),args)}
 fn create(&mut self,cls:u32)->u32{assert_eq!(self.api(Interface::Shell,"CreateInstance",[loader::OBJECT_BASE,cls,self.out,0]),0,"a classe documentada deve criar sua interface real");let p=self.read(self.out);assert_ne!(p,0);p}
 fn read(&self,p:u32)->u32{self.m.cpu().read_u32(p).unwrap()}
 fn model(&mut self,w:u32)->u32{assert_eq!(self.call(w,12,[0x0101593c,self.out,0]),0);let m=self.read(self.out);assert_ne!(m,w,"GetModel deve devolver IInterfaceModel, não alias de IWidget");m}
 fn image(&mut self)->u32{let mut bmp=vec![0;58];bmp[..2].copy_from_slice(b"BM");for(at,v)in[(2,58u32),(10,54),(14,40),(18,1),(22,1)]{bmp[at..at+4].copy_from_slice(&v.to_le_bytes());}bmp[26..28].copy_from_slice(&1u16.to_le_bytes());bmp[28..30].copy_from_slice(&24u16.to_le_bytes());bmp[54..57].copy_from_slice(&[0,0,255]);std::fs::write(self.root.join("widget.bmp"),bmp).unwrap();self.m.cpu_mut().write_mem(self.out,b"widget.bmp\0").unwrap();self.api(Interface::Shell,"LoadResObject",[loader::OBJECT_BASE,self.out,0,0])}
}
impl Drop for F{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.root);}}
#[test]fn widget_getmodel_is_typed_and_does_not_accept_an_unknown_interface(){let mut f=F::new();let w=f.create(0x01054a8f);let m=f.model(w);assert_eq!(f.call(w,2,[0x12345678,f.out,0]),3);assert_eq!(f.read(f.out),0);assert_eq!(f.call(m,2,[0x0101593a,f.out,0]),0);assert_eq!(f.read(f.out),m);assert_eq!(f.call(m,1,[0,0,0]),2);assert_eq!(f.call(m,1,[0,0,0]),1);assert_eq!(f.call(w,1,[0,0,0]),0);assert_eq!(f.call(m,0,[0,0,0]),14,"um modelo já liberado não pode ser ressuscitado");}
#[test]fn interface_model_retains_image_and_draws_through_the_real_canvas_after_save_restore(){let mut f=F::new();let w=f.create(0x01054a8f);let m=f.model(w);let image=f.image();f.call(m,5,[image,0x01013110,0]);assert_eq!(f.call(image,1,[0,0,0]),1);assert_eq!(f.call(m,6,[0x01001045,f.out,0]),3);assert_eq!(f.read(f.out),0);assert_eq!(f.call(m,6,[0x01013110,f.out,0]),0);assert_eq!(f.read(f.out),image);assert_eq!(f.call(image,1,[0,0,0]),1);let display=f.create(0x01001001);f.call(display,16,[f.out,0,0]);let bitmap=f.read(f.out);f.call(bitmap,2,[0x0101e443,f.out,0]);let canvas=f.read(f.out);f.m.cpu_mut().write_u32(f.out,3).unwrap();f.m.cpu_mut().write_u32(f.out+4,3).unwrap();f.call(w,7,[f.out,0,0]);assert_eq!(f.call(w,3,[0x801,0x153,0x220]),1);let state=f.m.grava_estado();f.m.restaura_estado(&state).unwrap();f.call(w,10,[canvas,4,5]);assert_eq!(f.m.screen().get_pixel(5,6),0xf800,"Draw usa a imagem retida pelo modelo e o alinhamento documentado");assert_eq!(f.call(w,1,[0,0,0]),0);assert_eq!(f.call(m,1,[0,0,0]),0);assert_eq!(f.call(image,0,[0,0,0]),0);}
#[test]fn interface_model_listener_receives_real_change_and_can_cancel_after_restore(){let mut f=F::new();let w=f.create(0x01054a8f);let m=f.model(w);let image=f.image();let listener=f.out+64;let context=f.out+96;let cb=loader::MODULE_BASE+0x100;let code=[0xe5912000u32,0xe5802000,0xe5912004,0xe5802004,0xe12fff1e];f.m.cpu_mut().write_mem(cb,&code.into_iter().flat_map(u32::to_le_bytes).collect::<Vec<_>>()).unwrap();f.m.cpu_mut().write_mem(listener,&[0;24]).unwrap();f.m.cpu_mut().write_u32(listener+8,cb).unwrap();f.m.cpu_mut().write_u32(listener+12,context).unwrap();assert_eq!(f.call(m,3,[listener,0,0]),0);f.call(m,5,[image,0x01013110,0]);assert_eq!(f.read(context),0x1000);assert_eq!(f.read(context+4),m);let state=f.m.grava_estado();f.m.restaura_estado(&state).unwrap();let cancel=f.read(listener+16);assert_ne!(cancel,0);f.entry(cancel,[listener,0,0,0]);assert_eq!(f.read(listener+16),0);f.m.cpu_mut().write_u32(context,0xdeadbeef).unwrap();f.call(m,5,[0,0x01013110,0]);assert_eq!(f.read(context),0xdeadbeef);f.call(image,1,[0,0,0]);f.call(m,1,[0,0,0]);f.call(w,1,[0,0,0]);}

#[test]fn modern_widget_oom_is_two_and_partial_model_allocation_rolls_back(){let mut f=F::new();let mut first=0;loop{let out=f.out;let rc=f.api(Interface::Shell,"CreateInstance",[loader::OBJECT_BASE,0x01001001,out,0]);if rc!=0{break;}if first==0{first=f.read(out);}}assert_ne!(first,0);f.call(first,1,[0,0,0]);let out=f.out;assert_eq!(f.api(Interface::Shell,"CreateInstance",[loader::OBJECT_BASE,0x01054a8f,out,0]),2,"AEEStdErr.h moderno define AEE_ENOMEMORY=2");assert_eq!(f.read(out),0);assert_eq!(f.api(Interface::Shell,"CreateInstance",[loader::OBJECT_BASE,0x01001001,out,0]),0,"o modelo parcial deve devolver o único slot livre");}
